// src/assets/fonts/embeddedFonts.js
//
// Montserrat (SIL Open Font License 1.1 — free to bundle and embed), base64-
// encoded and inlined directly as JS string constants rather than left as
// .woff FILES read from disk at runtime.
//
// Why inlined instead of fs.readFileSync()'d: this backend deploys to
// Vercel as a serverless function. Vercel traces which files a function
// actually needs (via @vercel/nft) by statically analyzing the code, and
// that tracer is known to sometimes miss non-JS asset files referenced
// through fs.readFileSync(path.join(__dirname, ...)) — the exact pattern
// a first version of this used. The failure mode is nasty specifically
// because it's invisible locally: `npm run dev` reads the real files off
// disk just fine, and it's only on Vercel, after a deploy, that the
// function would throw trying to read a font file that silently never made
// it into the deployed bundle. Making the font bytes a plain JS module
// export removes the file-tracing step from the equation entirely — these
// strings are part of the JS source, so they ship wherever the code that
// requires them ships, on any platform, with zero bundler configuration.
//
// Regenerate by re-running the one-off encode script if the fonts ever
// need to change (see the comment in imageCompositingService.js).

module.exports = {
  MONTSERRAT_800_WOFF_BASE64:
    "",
  MONTSERRAT_600_WOFF_BASE64:
    "",
};
